content.text:
Shipping is the root fault, and the impact chain runs through checkout and frontend to frontend-proxy. Accounting is restarting, but nothing synchronous calls it, so I'm treating its effect as contained. I'll write up the result.

```json
{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='shipping' AND span_name='POST quote' GROUP BY ALL",
          "claim": "Shipping's outgoing 'POST quote' client spans average about 675 ms in the incident window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE service_name='quote' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "The quote service's own server spans stay at about 0.3 ms, so the delay is not inside quote."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE service_name='shipping' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Shipping's /ship-order server spans stay at about 0.03 ms, so only the quote path is affected."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, round(avg(value),2) avg_v, round(max(value),2) max_v FROM abnormal_metrics_sum WHERE service_name='shipping' AND metric IN ('k8s.pod.network.errors','k8s.pod.network.io') GROUP BY ALL",
          "claim": "Shipping pod network error counters stay at zero, so the delay is not a transport-level fault."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "shipping",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) n, round(avg(c.duration)/1e6,1) caller_ms, round(avg(s.duration)/1e6,1) callee_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='checkout' AND s.service_name='shipping' GROUP BY ALL",
          "claim": "Checkout's HTTP POST to shipping /get-quote takes about 677 ms, matching shipping's slow server span."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) n, round(avg(c.duration)/1e6,1) caller_ms, round(avg(s.duration)/1e6,1) callee_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='frontend' AND s.service_name='checkout' GROUP BY ALL",
          "claim": "Frontend's PlaceOrder call to checkout takes about 697 ms, matching checkout's slow server span."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' GROUP BY ALL",
          "claim": "Frontend-proxy ingress spans average about 38 ms with a max of 711 ms, versus 5.7 ms normally."
        }
      ]
    }
  ]
}
